    private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private GradientDrawable outlined(int color,int radius,int border){GradientDrawable d=round(color,radius);d.setStroke(dp(1),border);return d;}
    private android.graphics.drawable.Drawable tinted(int id,int color){android.graphics.drawable.Drawable icon=ContextCompat.getDrawable(this,id);if(icon==null)return null;icon=icon.mutate();androidx.core.graphics.drawable.DrawableCompat.setTint(icon,color);return icon;}
    private Button button(String text,boolean solid){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);b.setTextColor(solid?Color.WHITE:BLUE);b.setBackgroundTintList(null);b.setBackground(round(solid?BLUE:0xffedf3ff,14));b.setPadding(dp(12),0,dp(12),0);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);return b;}
    private GradientDrawable topRounded(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);float r=dp(radius);d.setCornerRadii(new float[]{r,r,r,r,0,0,0,0});return d;}
