        int maxHeight=(int)(getResources().getDisplayMetrics().heightPixels*.60f);sheet.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(labels.length*72),maxHeight)));dialog.setContentView(sheet);android.view.Window win=dialog.getWindow();if(win!=null){win.setBackgroundDrawableResource(android.R.color.transparent);win.addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);android.view.WindowManager.LayoutParams p=win.getAttributes();p.gravity=Gravity.BOTTOM;p.width=android.view.WindowManager.LayoutParams.MATCH_PARENT;p.height=android.view.WindowManager.LayoutParams.WRAP_CONTENT;p.dimAmount=.35f;win.setAttributes(p);win.setNavigationBarColor(0xffffffff);win.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}dialog.show();if(win!=null)win.setLayout(-1,-2);
