    private int actionIcon(String label){if(label.contains("停止"))return R.drawable.ic_a_stop;if(label.contains("开始")||label.contains("继续"))return R.drawable.ic_a_play;if(label.contains("撤销"))return R.drawable.ic_a_undo;if(label.contains("清空")||label.contains("删除"))return R.drawable.ic_a_delete;if(label.contains("导入")||label.contains("导出")||label.contains("保存"))return R.drawable.ic_a_file;if(label.contains("绘制")||label.contains("画线"))return R.drawable.ic_a_edit;if(label.contains("坐标")||label.contains("定位")||label.contains("摇杆"))return R.drawable.ic_a_target;if(label.contains("地图"))return R.drawable.ic_a_pin;if(label.contains("路线")||label.contains("规划"))return R.drawable.ic_a_route;return R.drawable.ic_a_settings;}
    private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
    private String mapKey(){String local=prefs.getString("amap_key","");if(local!=null&&!local.trim().isEmpty())return local.trim();try{ApplicationInfo a=getPackageManager().getApplicationInfo(getPackageName(),PackageManager.GET_META_DATA);return a.metaData==null?"":a.metaData.getString("com.amap.api.v2.apikey","");}catch(Exception e){return "";}}
    private void askPrivacy(Bundle state,String key){new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("使用高德地图")
            .setMessage("地图、地点搜索及路线规划由高德提供，使用时高德 SDK 可能处理设备信息、网络信息和位置信息。选择同意后才会初始化 SDK；你可以先查看高德隐私政策。")
            .setNeutralButton("隐私政策",(d,w)->{openUrl("https://lbs.amap.com/pages/privacy/");})
            .setNegativeButton("暂不使用",null).setPositiveButton("同意并继续",(d,w)->{prefs.edit().putBoolean("amap_consent",true).apply();initializeMap(state,key);}).show();}
    private void initializeMap(Bundle state,String key){try{
        MapsInitializer.updatePrivacyShow(getApplicationContext(),true,true);MapsInitializer.updatePrivacyAgree(getApplicationContext(),true);
        ServiceSettings.updatePrivacyShow(getApplicationContext(),true,true);ServiceSettings.updatePrivacyAgree(getApplicationContext(),true);
        MapsInitializer.setApiKey(key);ServiceSettings.getInstance().setApiKey(key);
        mapView=new MapView(this);mapView.onCreate(state);if(resumed)mapView.onResume();mapContainer.removeAllViews();mapContainer.addView(mapView,new FrameLayout.LayoutParams(-1,-1));map=mapView.getMap();
        map.getUiSettings().setZoomControlsEnabled(false);map.getUiSettings().setScaleControlsEnabled(true);map.setMapType(prefs.getBoolean("satellite",false)?AMap.MAP_TYPE_SATELLITE:AMap.MAP_TYPE_NORMAL);
        if(selected==null)map.moveCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(34.23,108.94),12));else moveTo(selected);
        map.setOnMapClickListener(p->{if(mode==2)return;double[] w=MapCoordinates.toWgs(p.latitude,p.longitude);selected=w;selectedLabel=null;if(mode==1){undo.add(route.size());route.add(w.clone());revision++;}redraw();updateInfo();});
        penOverlay=new View(this);penOverlay.setBackgroundColor(Color.TRANSPARENT);penOverlay.setOnTouchListener((v,event)->handlePen(event));mapContainer.addView(penOverlay,new FrameLayout.LayoutParams(-1,-1));penOverlay.setVisibility(mode==2?View.VISIBLE:View.GONE);redraw();
    }catch(Exception e){android.util.Log.e("LocationMap","AMap initialization failed",e);toast("地图初始化失败，请检查 Key 和网络");}}
    private void setMode(int next){mode=next;if(penOverlay!=null)penOverlay.setVisibility(mode==2?View.VISIBLE:View.GONE);updateInfo();}
    private boolean handlePen(MotionEvent event){if(mode!=2||map==null)return false;if(event.getPointerCount()>1){if(penActive&&!undo.isEmpty()){int before=undo.remove(undo.size()-1);while(route.size()>before)route.remove(route.size()-1);revision++;redraw();updateInfo();}penActive=false;return true;}int a=event.getActionMasked();
        if(a==MotionEvent.ACTION_DOWN){undo.add(route.size());penActive=true;lastX=event.getX();lastY=event.getY();appendPen(lastX,lastY);return true;}
        if(a==MotionEvent.ACTION_MOVE&&penActive){float x=event.getX(),y=event.getY();if(Math.hypot(x-lastX,y-lastY)>=dp(8)){lastX=x;lastY=y;appendPen(x,y);}return true;}
        if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){penActive=false;return true;}return true;}
    private void appendPen(float x,float y){if(route.size()>=5000){toast("路线节点已达上限");penActive=false;return;}LatLng p=map.getProjection().fromScreenLocation(new Point((int)x,(int)y));if(p==null)return;double[] w=MapCoordinates.toWgs(p.latitude,p.longitude);route.add(w);selected=w;selectedLabel=null;revision++;redraw();updateInfo();}
    private LatLng display(double[] w){double[] p=MapCoordinates.toGcj(w[0],w[1]);return new LatLng(p[0],p[1]);}
    private void redraw(){if(map==null)return;map.clear();if(route.size()>1){ArrayList<LatLng> line=new ArrayList<>();for(double[] p:route)line.add(display(p));map.addPolyline(new PolylineOptions().addAll(line).color(BLUE).width(dp(5)));map.addMarker(new MarkerOptions().position(line.get(0)).title("起点"));map.addMarker(new MarkerOptions().position(line.get(line.size()-1)).title("终点"));}if(selected!=null){MarkerOptions marker=new MarkerOptions().position(display(selected)).title("选中位置");try{if(selectedMarkerIcon==null){android.graphics.drawable.Drawable d=ContextCompat.getDrawable(this,R.drawable.ic_a_pin);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(dp(36),dp(44),android.graphics.Bitmap.Config.ARGB_8888);d.setBounds(0,0,bitmap.getWidth(),bitmap.getHeight());d.draw(new android.graphics.Canvas(bitmap));selectedMarkerIcon=com.amap.api.maps.model.BitmapDescriptorFactory.fromBitmap(bitmap);}if(selectedMarkerIcon!=null)marker.icon(selectedMarkerIcon);}catch(RuntimeException e){android.util.Log.w("LocationMap","Could not create selected marker icon",e);}map.addMarker(marker);}}
    private void moveTo(double[] p){if(map!=null)map.animateCamera(CameraUpdateFactory.newLatLngZoom(display(p),16));}
    private void updateInfo(){if(info==null)return;if(selected==null){info.setText(mode==2?"手绘路线":mode==1?"逐点绘制路线":"选择模拟位置");coordinateDetail.setText(mode==2?"在地图上拖动画线":mode==1?"点击地图添加路线点":"点击地图或搜索地点");return;}info.setText(selectedLabel==null||selectedLabel.isEmpty()?"已选位置":selectedLabel);String state=mode==1?" · 逐点编辑":mode==2?" · 手绘中":"";coordinateDetail.setText(String.format(Locale.US,"%.6f, %.6f",selected[0],selected[1])+state+(route.isEmpty()?"":" · "+route.size()+" 个路线点"));}
    private void submitSearch(){String query=searchInput.getText().toString().trim();if(query.isEmpty()){toast("请输入地点或地址");return;}if(map==null){toast("地图尚未启用，请在设置中启用地图并检查网络");return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(searchInput.getWindowToken(),0);searchInput.clearFocus();search(query);}
    private void searchMessage(String message){searchResults.removeAllViews();TextView text=label(message,14,MUTED);text.setPadding(dp(18),dp(18),dp(18),dp(18));searchResults.addView(text);searchPanel.setVisibility(View.VISIBLE);}
    @Override public void onBackPressed(){if(searchPanel!=null&&searchPanel.getVisibility()==View.VISIBLE){searchGeneration++;searchPanel.setVisibility(View.GONE);return;}super.onBackPressed();}
    private void search(String q){final int generation=++searchGeneration;searchMessage("正在搜索…");try{Inputtips tips=new Inputtips(this,new InputtipsQuery(q,""));tips.setInputtipsListener((items,code)->{if(isFinishing()||generation!=searchGeneration)return;if(code!=1000){searchMessage("搜索失败（"+code+"），请检查网络后重试");return;}searchResults.removeAllViews();int count=0;if(items!=null)for(Tip t:items){if(t==null||t.getPoint()==null)continue;final double[] position=MapCoordinates.toWgs(t.getPoint().getLatitude(),t.getPoint().getLongitude());final String name=t.getName()==null?"地点":t.getName();String address=t.getAddress()==null?"":t.getAddress();LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(18),dp(12),dp(18),dp(12));TextView title=label(name,15,TEXT);title.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);row.addView(title);if(!address.isEmpty()){TextView detail=label(address,12,MUTED);detail.setPadding(0,dp(4),0,0);row.addView(detail);}row.setOnClickListener(v->{selected=position;selectedLabel=name;searchInput.setText(name);searchInput.setSelection(searchInput.length());searchInput.clearFocus();searchPanel.setVisibility(View.GONE);moveTo(selected);redraw();updateInfo();});searchResults.addView(row,new LinearLayout.LayoutParams(-1,-2));count++;}if(count==0)searchMessage("没有找到结果，请尝试其他关键词");else searchPanel.setVisibility(View.VISIBLE);});tips.requestInputtipsAsyn();}catch(Exception e){searchMessage("搜索初始化失败，请稍后重试");}}
    private void routeMenu(){String[] options={"开始路线模拟","逐点绘制","手指画线","完成绘制","撤销上一次","步行道路规划","保存路线","路线库","导入 GPX","导出 GPX","清空路线","停止模拟"};String[] details={"设置速度和循环方式","点击地图添加路线点","在地图上拖动画路线","退出路线编辑","撤销最近一次绘制","连接起点与终点的步行路线","将当前路线保存到路线库","查看已保存的路线","从文件选择路线或轨迹","将当前路线保存为文件","删除地图上的当前路线","结束当前模拟"};int[] order={8,0,1,2,3,5,6,7,10,11,4,9};showActionSheet("路线工具","绘制、管理和播放你的路线",options,details,n->{switch(order[n]){case 0:setMode(1);toast("逐点点击地图添加路线");break;case 1:setMode(2);toast("在地图上拖动手指画线；结束后可移动地图");break;case 2:setMode(0);break;case 3:undoRoute();break;case 4:new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setMessage("清空当前路线？").setNegativeButton("取消",null).setPositiveButton("清空",(a,b)->{route.clear();undo.clear();revision++;redraw();updateInfo();}).show();break;case 5:planWalk();break;case 6:saveRoute();break;case 7:routes();break;case 8:playRoute();break;case 9:stopSimulation();break;case 10:importGpx();break;case 11:exportGpx();break;}});}
    private void undoRoute(){if(undo.isEmpty()){toast("没有可撤销的节点");return;}int size=undo.remove(undo.size()-1);while(route.size()>size)route.remove(route.size()-1);revision++;redraw();updateInfo();}
    // Adapted from Lecheeel/Portal AMapRoutePlanner: each request owns its callback.
    private void planWalk(){if(map==null){toast("地图尚未启用，请在设置中启用地图并检查网络");return;}if(route.size()<2){toast("请先添加起点和终点");return;}if(planning){toast("正在规划路线");return;}final int expected=revision;double[] start=MapCoordinates.toGcj(route.get(0)[0],route.get(0)[1]),end=MapCoordinates.toGcj(route.get(route.size()-1)[0],route.get(route.size()-1)[1]);planning=true;
        try{RouteSearch search=new RouteSearch(this);search.setRouteSearchListener(new RouteSearch.OnRouteSearchListener(){
            @Override public void onWalkRouteSearched(WalkRouteResult result,int code){planning=false;if(isFinishing())return;if(expected!=revision){toast("路线已变化，规划结果已忽略");return;}if(code!=1000||result==null||result.getPaths()==null||result.getPaths().isEmpty()){toast("步行规划失败（"+code+"），请检查网络与高德 Key 权限");return;}WalkPath path=result.getPaths().get(0);ArrayList<double[]> points=new ArrayList<>();if(path.getSteps()!=null)for(WalkStep step:path.getSteps())if(step.getPolyline()!=null)for(LatLonPoint p:step.getPolyline())points.add(MapCoordinates.toWgs(p.getLatitude(),p.getLongitude()));if(points.size()<2||points.size()>5000){toast("规划结果无效或路线过长");return;}route.clear();route.addAll(points);undo.clear();revision++;setMode(0);selected=route.get(route.size()-1).clone();selectedLabel=null;redraw();updateInfo();toast("步行路线已规划，可保存或开始模拟");}
            @Override public void onBusRouteSearched(BusRouteResult r,int c){} @Override public void onDriveRouteSearched(DriveRouteResult r,int c){} @Override public void onRideRouteSearched(RideRouteResult r,int c){}
        });RouteSearch.FromAndTo endpoints=new RouteSearch.FromAndTo(new LatLonPoint(start[0],start[1]),new LatLonPoint(end[0],end[1]));search.calculateWalkRouteAsyn(new RouteSearch.WalkRouteQuery(endpoints));toast("正在规划步行路线…");}catch(Exception e){planning=false;toast("规划初始化失败，请检查 Key 和网络");}}
    private JSONArray read(String key){try{return new JSONArray(prefs.getString(key,"[]"));}catch(JSONException e){return new JSONArray();}}
    private boolean write(String key,JSONArray a){return prefs.edit().putString(key,a.toString()).commit();}
    private JSONObject point(double[] p)throws JSONException{return new JSONObject().put("lat",p[0]).put("lon",p[1]);}
    private JSONArray single(double[] p){JSONArray a=new JSONArray();try{a.put(point(p));}catch(JSONException ignored){}return a;}
    private JSONArray routeJson(){JSONArray a=new JSONArray();for(double[] p:route)try{a.put(point(p));}catch(JSONException ignored){}return a;}
    private void nameDialog(String title,java.util.function.Consumer<String> accept){EditText input=new EditText(this);input.setSingleLine();input.setHint("请输入名称");new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle(title).setView(input).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{String name=input.getText().toString().trim();if(name.isEmpty()){toast("名称不能为空");return;}accept.accept(name);}).show();}
    private void addFavorite(){if(selected==null){toast("请先选择位置");return;}double[] p=selected.clone();nameDialog("收藏位置",name->{try{JSONArray a=read("favorites");a.put(point(p).put("name",name));toast(write("favorites",a)?"已收藏":"保存失败");}catch(JSONException e){toast("保存失败");}});}
    private void favorites(){JSONArray a=read("favorites");if(a.length()==0){toast("还没有收藏");return;}String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.optJSONObject(i).optString("name","未命名");AlertDialog dialog=new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("收藏位置：点击传送，长按删除").setItems(names,(d,i)->{JSONObject p=a.optJSONObject(i);if(p==null)return;selected=new double[]{p.optDouble("lat"),p.optDouble("lon")};selectedLabel=p.optString("name","已选位置");moveTo(selected);redraw();updateInfo();startSimulation(single(selected),1.4);}).setNegativeButton("关闭",null).create();dialog.setOnShowListener(d->dialog.getListView().setOnItemLongClickListener((parent,view,i,id)->{confirmDelete("favorites",a,i,dialog);return true;}));dialog.show();}
    private void saveRoute(){if(route.size()<2){toast("至少需要两个路线节点");return;}JSONArray nodes=routeJson();nameDialog("保存路线",name->{try{JSONArray a=read("routes");a.put(new JSONObject().put("name",name).put("points",nodes));toast(write("routes",a)?"路线已保存":"保存失败");}catch(JSONException e){toast("保存失败");}});}
    private void routes(){JSONArray a=read("routes");if(a.length()==0){toast("还没有保存路线");return;}String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.optJSONObject(i).optString("name","未命名");AlertDialog dialog=new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("路线库：点击载入，长按删除").setItems(names,(d,i)->{JSONArray nodes=a.optJSONObject(i).optJSONArray("points");if(nodes==null)return;route.clear();undo.clear();for(int n=0;n<nodes.length();n++){JSONObject p=nodes.optJSONObject(n);if(p!=null)route.add(new double[]{p.optDouble("lat"),p.optDouble("lon")});}revision++;setMode(0);if(!route.isEmpty()){selected=route.get(0).clone();selectedLabel=null;moveTo(selected);}redraw();updateInfo();toast("路线已载入，可开始模拟");}).setNegativeButton("关闭",null).create();dialog.setOnShowListener(d->dialog.getListView().setOnItemLongClickListener((parent,view,i,id)->{confirmDelete("routes",a,i,dialog);return true;}));dialog.show();}
    private void confirmDelete(String key,JSONArray a,int index,AlertDialog list){new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setMessage("确定删除？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{JSONArray b=new JSONArray();for(int i=0;i<a.length();i++)if(i!=index)b.put(a.opt(i));if(write(key,b)){list.dismiss();toast("已删除");}else toast("删除失败");}).show();}
    private static final int IMPORT_GPX=8701, EXPORT_GPX=8702;
    private void importGpx(){try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/gpx+xml","application/xml","text/xml","application/octet-stream"});startActivityForResult(intent,IMPORT_GPX);}catch(Exception e){toast("无法打开文件选择器");}}
    private void exportGpx(){if(route.size()<2){toast("请先绘制或载入路线");return;}try{pendingGpx=routeJson().toString();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/gpx+xml").putExtra(Intent.EXTRA_TITLE,"路线.gpx");startActivityForResult(intent,EXPORT_GPX);}catch(Exception e){pendingGpx=null;toast("无法打开文件保存器");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==EXPORT_GPX)pendingGpx=null;return;}Uri uri=data.getData();
        if(request==IMPORT_GPX){new Thread(()->{try(java.io.InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new java.io.IOException();ArrayList<double[]> loaded=GpxRoutes.read(in);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;Runnable apply=()->{route.clear();route.addAll(loaded);undo.clear();revision++;setMode(0);selected=route.get(0).clone();selectedLabel=null;moveTo(selected);redraw();updateInfo();toast("GPX 路线已载入，可保存到路线库");};if(route.isEmpty())apply.run();else new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("导入 GPX").setMessage("用导入的路线替换当前地图上的路线？已保存的路线库不会改变。").setNegativeButton("取消",null).setPositiveButton("替换",(d,w)->apply.run()).show();});}catch(Exception e){runOnUiThread(()->toast("GPX 导入失败："+(e.getMessage()==null?"请检查文件":e.getMessage())));}}).start();}
        else if(request==EXPORT_GPX){String snapshot=pendingGpx;pendingGpx=null;if(snapshot==null){toast("导出已取消，请重试");return;}new Thread(()->{try{JSONArray dataPoints=new JSONArray(snapshot);ArrayList<double[]> export=new ArrayList<>();for(int i=0;i<dataPoints.length();i++){JSONObject p=dataPoints.getJSONObject(i);export.add(new double[]{p.getDouble("lat"),p.getDouble("lon")});}String xml=GpxRoutes.write(export);try(java.io.OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new java.io.IOException();out.write(xml.getBytes(java.nio.charset.StandardCharsets.UTF_8));}runOnUiThread(()->toast("路线已导出为 GPX"));}catch(Exception e){runOnUiThread(()->toast("导出失败，请重试"));}}).start();}}
    private void playRoute(){if(route.size()<2){toast("请先绘制或载入路线");return;}LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText input=new EditText(this),loopsInput=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setHint("速度（米/秒）");input.setText("1.4");loopsInput.setInputType(InputType.TYPE_CLASS_NUMBER);loopsInput.setHint("循环次数（1–999）");loopsInput.setText("1");form.addView(input);form.addView(loopsInput);android.widget.Spinner playback=new android.widget.Spinner(this);playback.setAdapter(new android.widget.ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"循环：终点直线返回起点", "往返：沿原路线返回"}));form.addView(playback);form.addView(label("循环次数：往返模式中一次包含去程与回程。",13,MUTED));JSONArray snapshot=routeJson();new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("开始路线模拟").setView(form).setNegativeButton("取消",null).setPositiveButton("开始",(d,w)->{try{double speed=Double.parseDouble(input.getText().toString());int loops=Integer.parseInt(loopsInput.getText().toString());if(speed<=0||speed>100||!Double.isFinite(speed)||loops<1||loops>999)throw new IllegalArgumentException();startSimulation(snapshot,speed,loops,playback.getSelectedItemPosition()==1);}catch(Exception e){toast("速度须为 0–100 米/秒，循环次数须为 1–999");}}).show();}
    private void startSimulation(JSONArray points,double speed){startSimulation(points,speed,1);}
    private void startSimulation(JSONArray points,double speed,int loops){startSimulation(points,speed,loops,false);}
    private void startSimulation(JSONArray points,double speed,int loops,boolean pingPong){
        if(ContextCompat.checkSelfPermission(this,android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){pendingPoints=points.toString();pendingSpeed=speed;pendingLoops=loops;pendingPingPong=pingPong;requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},8602);return;}
        AppOpsManager ops=(AppOpsManager)getSystemService(APP_OPS_SERVICE);int op=ops.checkOpNoThrow(AppOpsManager.OPSTR_MOCK_LOCATION,android.os.Process.myUid(),getPackageName());if(op!=AppOpsManager.MODE_ALLOWED){new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("选择模拟位置应用").setMessage("请在开发者选项中，将本应用设为模拟位置信息应用，然后返回重试。").setNegativeButton("取消",null).setPositiveButton("打开设置",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS))).show();return;}try{startForegroundService(new Intent(this,ServiceGo.class).putExtra("points",points.toString()).putExtra("speed",speed).putExtra("loops",loops).putExtra("ping_pong",pingPong));simulationStatus.setText("正在切换位置…");}catch(Exception e){toast("启动失败："+e.getMessage());}}
    private void stopSimulation(){try{stopService(new Intent(this,ServiceGo.class));toast("模拟已停止");}catch(Exception e){toast("停止失败");}}
    private void settingsMenu(){String[] options={"启用地图","普通／卫星地图","手动输入坐标","显示悬浮摇杆","定位状态","停止模拟","检查更新","高德隐私政策"};String[] details={"启用高德地图和地点搜索","切换地图显示方式","输入 WGS-84 经纬度","显示可拖动的方向摇杆","查看模拟授权与通道状态","结束当前定位或路线","查看本项目最新版本","查看高德地图隐私说明"};showActionSheet("设置","地图、定位与应用选项",options,details,n->{switch(n){case 0:if(map!=null){toast("地图已启用");break;}String key=mapKey();if(key==null||key.isEmpty()){toast("地图暂不可用，请检查网络或稍后重试");break;}if(prefs.getBoolean("amap_consent",false))initializeMap(null,key);else askPrivacy(null,key);break;case 1:if(map==null){toast("地图尚未启用，请先启用地图");break;}boolean satellite=!prefs.getBoolean("satellite",false);prefs.edit().putBoolean("satellite",satellite).apply();map.setMapType(satellite?AMap.MAP_TYPE_SATELLITE:AMap.MAP_TYPE_NORMAL);break;case 2:manualCoordinate();break;case 3:showOverlay();break;case 4:showSimulationStatus();break;case 5:stopSimulation();break;case 6:openUrl("https://github.com/xieyinch/location-simulator/releases");break;case 7:openUrl("https://lbs.amap.com/pages/privacy/");break;}});}
    private void manualCoordinate(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText lat=new EditText(this),lon=new EditText(this);lat.setHint("纬度 WGS-84");lon.setHint("经度 WGS-84");lat.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);lon.setInputType(lat.getInputType());form.addView(lat);form.addView(lon);new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("输入坐标").setView(form).setNegativeButton("取消",null).setPositiveButton("选择",(d,w)->{try{double a=Double.parseDouble(lat.getText().toString()),b=Double.parseDouble(lon.getText().toString());if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a)>90||Math.abs(b)>180)throw new IllegalArgumentException();selected=new double[]{a,b};selectedLabel=null;moveTo(selected);redraw();updateInfo();}catch(Exception e){toast("坐标格式或范围有误");}}).show();}
    private void showOverlay(){if(!Settings.canDrawOverlays(this)){new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setMessage("请先授权显示悬浮窗，再返回点击圆形摇杆。").setNegativeButton("取消",null).setPositiveButton("授权",(d,w)->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())))).show();return;}try{startForegroundService(new Intent(this,ServiceGo.class).setAction(ServiceGo.ACTION_SHOW_CONTROLS));}catch(Exception e){toast("请先启动位置模拟");}}
    private boolean isSimulationActive(){SharedPreferences state=getSharedPreferences(ServiceGo.STATUS_PREFS,MODE_PRIVATE);return state.getBoolean("active",false)&&System.currentTimeMillis()-state.getLong("time",0)<10000;}
    private void renderSimulationStatus(){String status=getSharedPreferences(ServiceGo.STATUS_PREFS,MODE_PRIVATE).getString("text","未启动位置模拟");boolean active=isSimulationActive();if(simulationStatus!=null)simulationStatus.setText(status);if(go!=null)go.setText(active?"停止模拟":"开始模拟");if(primaryIcon!=null)primaryIcon.setImageDrawable(tinted(active?R.drawable.ic_a_stop:R.drawable.ic_a_play,Color.WHITE));if(switchPosition!=null)switchPosition.setVisibility(active?View.VISIBLE:View.GONE);SharedPreferences state=getSharedPreferences(ServiceGo.STATUS_PREFS,MODE_PRIVATE);if(pauseRoute!=null){boolean hasRoute=active&&state.getBoolean("route",false);pauseRoute.setVisibility(hasRoute?View.VISIBLE:View.GONE);pauseRoute.setText(state.getBoolean("paused",false)?"继续路线":"暂停路线");}}
    private void showSimulationStatus(){String status=getSharedPreferences(ServiceGo.STATUS_PREFS,MODE_PRIVATE).getString("text","未启动位置模拟");int op=((AppOpsManager)getSystemService(APP_OPS_SERVICE)).checkOpNoThrow(AppOpsManager.OPSTR_MOCK_LOCATION,android.os.Process.myUid(),getPackageName());new AlertDialog.Builder(this,R.style.AppTheme_LightDialog).setTitle("定位状态").setMessage(status+"\n\n模拟位置应用："+(op==AppOpsManager.MODE_ALLOWED?"已选择本应用":"未选择本应用")+"\n\n系统接收模拟位置不代表所有目标 App 都会采用该位置。若无效，请检查系统定位开关、目标应用定位方式及电池限制。") .setPositiveButton("知道了",null).setNeutralButton("开发者选项",(d,w)->{try{startActivity(new Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));}catch(Exception e){toast("无法打开开发者选项");}}).show();}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==8602){String data=pendingPoints;double speed=pendingSpeed;pendingPoints=null;if(ContextCompat.checkSelfPermission(this,android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED && data!=null){try{startSimulation(new JSONArray(data),speed,pendingLoops,pendingPingPong);}catch(JSONException e){toast("位置数据无效，请重新选择");}}else toast("请授予精确位置权限后重试");}}
    private void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("无法打开浏览器");}}
    private void restoreState(Bundle state){pendingGpx=state.getString("pending_gpx");selectedLabel=state.getString("selected_label");mode=state.getInt("mode",0);try{JSONArray a=new JSONArray(state.getString("route","[]"));for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);route.add(new double[]{p.getDouble("lat"),p.getDouble("lon")});}String v=state.getString("selected");if(v!=null){JSONObject p=new JSONObject(v);selected=new double[]{p.getDouble("lat"),p.getDouble("lon")};}}catch(JSONException ignored){}}
    @Override protected void onResume(){super.onResume();resumed=true;if(!receiverRegistered){if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(statusReceiver,new android.content.IntentFilter(ServiceGo.ACTION_STATUS),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(statusReceiver,new android.content.IntentFilter(ServiceGo.ACTION_STATUS));receiverRegistered=true;}renderSimulationStatus();if(mapView!=null)mapView.onResume();} @Override protected void onPause(){resumed=false;if(receiverRegistered){unregisterReceiver(statusReceiver);receiverRegistered=false;}if(mapView!=null)mapView.onPause();super.onPause();}
    @Override protected void onDestroy(){searchGeneration++;revision++;if(mapView!=null)mapView.onDestroy();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("mode",mode);out.putString("route",routeJson().toString());out.putString("pending_gpx",pendingGpx);out.putString("selected_label",selectedLabel);if(selected!=null)try{out.putString("selected",point(selected).toString());}catch(JSONException ignored){}if(mapView!=null)mapView.onSaveInstanceState(out);}
